/* Regenerates every deliverable of the final design that is an image or a generated file.

   node /home/user/tiger-browser/design/final/render.cjs                 everything: 52 screens at 2x into shots/,
                                                                         shots/components.png, shots/components-dark.png, icons.svg
   node .../render.cjs 02-ask-panel 09b-attached                         only these
   node .../render.cjs --scale=1 --out=/some/dir 01-browse               cheap 1x proof elsewhere
   node .../render.cjs --scale=1 --out=/some/dir --clip=0,0,620,420 01-browse    a region (x,y,w,h)
   node .../render.cjs --icons                                           only icons.svg

   Needs Playwright (preinstalled globally) and nothing else: fonts are local woff2 subsets.
   Fails (exit 1) when a character falls outside the font subset, a font does not load, the
   document overflows the window, a text box is clipped, or a pointer target is under 28 px.
   The component sheet is a document, not a window: it is captured at its full height and only
   the font checks apply to it. */
const path = require("node:path");
const fs = require("node:fs");
const { chromium } = require("playwright");

const root = __dirname;
const index = "file://" + path.join(root, "prototype", "index.html");

const SCREENS = [
  "01-browse",
  "02-ask-panel",
  "03-share-preview",
  "03b-share-update",
  "03c-crossing",
  "03c-shared",
  "04-space-home",
  "05-cannot-share",
  "05b-private-window",
  "06-first-run",
  "07-dark-01-browse",
  "07-dark-02-ask-panel",
  "07-dark-04-space-home",
  "07-dark-05b-private-window",
  "08-command",
  "09-attach-preview",
  "09b-attached",
  "10a-stale",
  "10b-shared-elsewhere",
  "10c-after-navigation",
  "11-unshare-confirm",
  "11b-citation-unavailable",
  "12-model-menu",
  "13a-streaming-with-stop",
  "13b-answer-failed",
  "13c-answer-stopped",
  "14-many-tabs",
  "14b-sidebar-collapsed",
  /* part 2 */
  "15a-permission-prompt",
  "15b-downloads",
  "15c-find-in-page",
  "15d-notice",
  "16a-space-switcher",
  "16a2-create-space",
  "16b-members-and-invites",
  "16c-accept-invite",
  "16d-activity",
  "17-share-thread-confirm",
  "17b-share-thread-ready",
  "18a-export-menu",
  "18b-google-not-connected",
  "18c-export-done",
  "19-settings",
  "20a-sign-in",
  "20b-offline-reconnecting",
  "20c-page-load-error",
  "20d-tab-crashed",
  "21-item-detail",
  "22-new-tab",
  "23-dark-17-share-thread-confirm",
  "23-dark-19-settings",
  "23-dark-21-item-detail",
  "components",
  "components-dark",
];

/* icons.svg: the one file with every icon, named. Generated from prototype/icons.js (the set the
   prototype draws with), so the two cannot differ. Each icon is a <symbol id="i-name"> on the
   16 px grid; the same file also lays them out with their names, so opening it shows the set. */
function writeIcons() {
  const vm = require("node:vm");
  const ctx = {};
  vm.createContext(ctx);
  vm.runInContext(fs.readFileSync(path.join(root, "prototype", "icons.js"), "utf8") + ";this.ICONS = ICONS;", ctx);
  const names = Object.keys(ctx.ICONS);
  const cols = 6, cw = 168, rh = 36, pad = 24;
  const rows = Math.ceil(names.length / cols);
  const w = pad * 2 + cols * cw, h = pad * 2 + rows * rh;
  const symbols = names.map((n) => `    <symbol id="i-${n}" viewBox="0 0 16 16">${ctx.ICONS[n]}</symbol>`).join("\n");
  const cells = names
    .map((n, i) => {
      const x = pad + (i % cols) * cw, y = pad + Math.floor(i / cols) * rh;
      return `  <use href="#i-${n}" x="${x}" y="${y + 6}" width="16" height="16"/><text class="n" x="${x + 28}" y="${y + 18}">${n}</text>`;
    })
    .join("\n");
  const svg = `<?xml version="1.0" encoding="UTF-8"?>
<!-- Tiger icon set: ${names.length} icons. Own drawings on a 16 px grid, 1.5 px stroke, round caps and joins,
     no fills except where a path says so. Generated by render.cjs from prototype/icons.js: edit that file.
     Use: <svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5"
          stroke-linecap="round" stroke-linejoin="round"><use href="icons.svg#i-cross"/></svg>
     At another size keep the stroke at 1.5 CSS px: stroke-width = 1.5 * 16 / size (1.25 px inside key caps). -->
<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" color="#2a2927">
  <style>.n { font: 11px ui-monospace, "SF Mono", Menlo, monospace; fill: #5b5a57; stroke: none; }</style>
  <defs>
${symbols}
  </defs>
  <rect width="${w}" height="${h}" fill="#fdfdfc" stroke="none"/>
${cells}
</svg>
`;
  fs.writeFileSync(path.join(root, "icons.svg"), svg);
  console.log(path.join(root, "icons.svg") + `  (${names.length} icons)`);
}

(async () => {
  const args = process.argv.slice(2);
  const opt = (name, fallback) => {
    const hit = args.find((a) => a.startsWith(`--${name}=`));
    return hit ? hit.slice(name.length + 3) : fallback;
  };
  const scale = Number(opt("scale", "2"));
  const out = path.resolve(opt("out", path.join(root, "shots")));
  const clipArg = opt("clip", "");
  const theme = opt("theme", "");
  const clip = clipArg ? (([x, y, width, height]) => ({ x, y, width, height }))(clipArg.split(",").map(Number)) : undefined;
  const only = args.filter((a) => !a.startsWith("--"));
  const list = only.length ? only : SCREENS;
  if (!only.length || args.includes("--icons")) writeIcons();
  if (args.includes("--icons") && !only.length) return;
  fs.mkdirSync(out, { recursive: true });
  const charset = new Set(fs.readFileSync(path.join(root, "prototype", "fonts", "charset.txt"), "utf8"));

  const browser = await chromium.launch();
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: scale });
  const page = await context.newPage();
  const problems = [];
  page.on("pageerror", (e) => problems.push(`script error: ${e.message}`));
  page.on("requestfailed", (r) => problems.push(`request failed: ${r.url()}`));

  for (const id of list) {
    /* 03c-crossing is the share sequence frozen 150 ms after the server's answer */
    await page.goto(`${index}?screen=${id}${theme ? `&theme=${theme}` : ""}${id === "03c-crossing" ? "&t=150" : ""}`);
    await page.evaluate(async () => {
      await document.fonts.ready;
      /* force every declared face to load, then wait again, so no frame is captured in fallback */
      await Promise.all([...document.fonts].map((f) => f.load().catch(() => null)));
      await document.fonts.ready;
    });
    await page.waitForFunction(() => document.documentElement.dataset.ready === "1", null, { timeout: 5000 }).catch(() => problems.push(`${id}: screen did not finish drawing`));
    const report = await page.evaluate(() => {
      const visible = (el) => {
        const r = el.getBoundingClientRect();
        return r.width > 0 && r.height > 0;
      };
      const label = (el) => (el.getAttribute("aria-label") || el.textContent || "").trim().slice(0, 24) || el.className;
      /* one-line text that is cut without the fade mask */
      const clipped = [...document.querySelectorAll(".st-label, .btn, .st-act, .zone-label, .space-name, .msg-name, .ledger-what, .model-name, .who-name, .picker-name, th, .seg-item, .pal-title, .field-label")]
        .filter((el) => visible(el) && el.scrollWidth > el.clientWidth + 1)
        .map(label);
      const small = [...document.querySelectorAll(".window button, .window a")]
        .filter((el) => visible(el) && !el.closest(".view .m-doc, .view .m-news, .view .m-bank, .view .m-note, .view .m-grid, .view .m-chat"))
        .filter((el) => {
          const r = el.getBoundingClientRect();
          /* hit area extended by ::after or by the row the control sits in */
          const pad = el.matches(".cite, .link, .zone-link, .st-x, .source-text") ? 6 : el.matches(".st-act") ? 4 : 0;
          return Math.min(r.width, r.height) + 2 * pad < 27.5;
        })
        .map((el) => `${label(el)} (${Math.round(el.getBoundingClientRect().width)}x${Math.round(el.getBoundingClientRect().height)})`);
      return {
        text: document.body.innerText,
        failed: [...document.fonts].filter((f) => f.status !== "loaded").map((f) => `${f.family} ${f.weight}`),
        overflow: document.documentElement.scrollWidth > 1440 || document.documentElement.scrollHeight > 900,
        clipped,
        small,
      };
    });
    const missing = [...new Set([...report.text].filter((ch) => ch > " " && ch !== " " && !charset.has(ch)))];
    if (missing.length) problems.push(`${id}: characters outside the font subset: ${missing.join(" ")}`);
    if (report.failed.length) problems.push(`${id}: fonts not loaded: ${report.failed.join(", ")}`);
    const sheet = id.startsWith("components");
    if (!sheet && report.overflow) problems.push(`${id}: document overflows 1440 x 900`);
    if (!sheet && report.clipped.length) problems.push(`${id}: clipped text: ${[...new Set(report.clipped)].join(" | ")}`);
    if (!sheet && report.small.length) problems.push(`${id}: targets under 28 px: ${[...new Set(report.small)].join(" | ")}`);
    await page.screenshot({ path: path.join(out, `${id}.png`), clip, fullPage: sheet && !clip });
    console.log(path.join(out, `${id}.png`));
  }
  await browser.close();
  if (problems.length) {
    console.error("\n" + problems.join("\n"));
    process.exitCode = 1;
  }
})();
